func _try_ledge_grab() -> bool:
	if level == null or _no_grab > 0.0:
		return false
	var dir := horizontal_input()
	if not (jump or dir == facing):
		return false
	var cx := floori(global_position.x + facing * 0.5)
	var body_x := floori(global_position.x)
	for cy in range(floori(global_position.y) + 1, floori(global_position.y + HANG_HANDS + 1.0)):
		var top := float(cy + 1)
		# a step low enough to jump onto is not a ledge
		if top - global_position.y < 1.9:
			continue
		# the hang position is close to where the body is now (no big snaps)
		var snap := (top - HANG_HANDS) - global_position.y
		if snap > 0.6 or snap < -0.9:
			continue
		if level.solid(cx, cy) and not level.solid(cx, cy + 1) and not level.solid(cx, cy + 2) \
				and not level.solid(body_x, cy) and not level.solid(body_x, cy + 1):
			var face := float(cx) if facing > 0 else float(cx + 1)
			if absf(face - global_position.x) > 0.75:
				continue
			_grab(Vector2(face, top))
			return true
	return false

func _wall_slide(delta: float) -> void:
	velocity.x = facing * 0.5
	velocity.y = maxf(velocity.y - GRAVITY * delta, -WALL_SLIDE_FALL)
	_slide_move()
	if is_on_floor():
		_land()
		return
	var dir := horizontal_input()
	if _try_ledge_grab():
		return
	if not is_on_wall() or dir != facing:
		if state_time > 0.15:
			_enter_air()
		return
	# WallJumpPrep: turn away and jump (JumpData.CanWallJump after jump was released)
	if jump_pressed:
		stats["wall_jumps"] += 1
		_enter(S.WALL_JUMP)
		_set_facing(-facing)
		_play("wall_jump_prep", 0.05, 2.4, 0.6)

func _wall_jump(delta: float) -> void:
	velocity = Vector3(facing * 0.5, 0.0, 0.0)
	_slide_move()
	if state_time > 0.12:
		_launch(JUMP_SPEED * 1.02, "jump_running", 0.05, 1.2, 0.15)

func _notice() -> void:
	var dx: float = target.global_position.x - fighter.global_position.x
	var dy: float = target.global_position.y - fighter.global_position.y
	if absf(dy) > 3.5 or target.is_dead():
		return
	var in_front := signf(dx) == fighter.facing
	# behind its back a bot only senses you right next to it, or running close by
	var heard: bool = absf(dx) < 0.7 or (absf(dx) < 2.5 and target.state == Fighter.S.RUN)
	if (in_front and absf(dx) < 8.0) or heard or fighter.hp < fighter.max_hp:
		fighter.aware = true
	# noise: fighting nearby
	if absf(dx) < 5.0 and target.state == Fighter.S.ATTACK and target.attack_id != "":
		fighter.aware = true

func _physics_process(delta: float) -> void:
	timer += delta
	match state:
		"ready":
			for other in get_tree().get_nodes_in_group("fighters"):
				var f: Fighter = other
				if not f.is_dead() and _on_plate(f) and f.is_on_floor():
					state = "armed"
					timer = 0.0
					Audio.play_at("ui_click", Vector3((x0 + x1) / 2.0, floor_y, 0), level, 6.0, 0.6)
					_glow.light_energy = 2.5
					break
		"armed":
			if timer >= ARM_DELAY:
				_shoot()
		"fired":
			if timer >= 0.08 and timer < 0.5:
				for other in get_tree().get_nodes_in_group("fighters"):
					var f: Fighter = other
					if not f.is_dead() and _on_plate(f):
