						f.kill_by_spikes()
						if level and level.has_method("spawn_hit"):
							level.spawn_hit(f.global_position + Vector3(0, 0.6, 0), 1.0, true)
			if timer >= HOLD:

func _on_player_died(_f: Fighter, _attacker: Fighter) -> void:
	deaths += 1
	GameState.record_death()
	Audio.play("fail")
	_respawn_timer = 2.6
	if hud:
		hud.show_ko()

# Back to the last checkpoint with full HP; enemies that were chasing reset.
func _respawn() -> void:
	var at: Vector3 = spawn_point
	for c in checkpoints:
		if c["active"]:
			at = c["pos"]
	player.respawn(at)
	_cam_x = at.x
	for e in enemies:
		if is_instance_valid(e) and not e.is_dead() and absf(e.global_position.x - at.x) < 6.0:
			e.global_position.x = at.x + 7.0 * signf(e.global_position.x - at.x + 0.01)
	if hud:
		hud.hide_ko()

func _unhandled_input(event: InputEvent) -> void:
	if visible and event.is_action_pressed("pause"):
		get_viewport().set_input_as_handled()
		closed.emit()

func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventMouseButton and event.pressed and event.button_index == MOUSE_BUTTON_LEFT:
		_select(hovered)
	elif event.is_action_pressed("move_left") or event.is_action_pressed("move_right"):
		var i := ORDER.find(selected)
		i = (i + (1 if event.is_action_pressed("move_right") else -1) + ORDER.size()) % ORDER.size()
		_select(ORDER[i])
	elif event.is_action_pressed("pause"):
		GameState.go_to("main_menu")
